import {
	__experimentalToolsPanel as ToolsPanel,
	__experimentalToolsPanelItem as ToolsPanelItem,
} from '@wordpress/components';
import { Notice } from '@wordpress/ui';
import { useCallback } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { VALID_BACKGROUND_CLIP_VALUES } from '@wordpress/style-engine';
import BackgroundClipControl from '../background-clip-control';
import BackgroundImageControl from '../background-image-control';
import ColorGradientDropdownItem from './color-gradient-dropdown-item';
import { useHasBackgroundColorPanel } from './color-panel';
import { useColorGradientSettings } from './hooks';
import { useToolsPanelDropdownMenuProps } from './utils';
import { setImmutably } from '../../utils/object';
import {
	extractPresetSlug,
	encodeColorValueWithPalette,
} from '../../utils/color-values';
import type {
	BackgroundPanelProps,
	PanelResetAllFilter,
	PanelStyle,
	StyleSettings,
	StyleToolsPanelProps,
} from './types';

const DEFAULT_CONTROLS: Record< string, boolean > = {
	backgroundImage: true,
	backgroundColor: true,
	gradient: true,
	backgroundClip: false,
};

/**
 * Checks site settings to see if the requested feature's control may be used.
 *
 * @param settings Site settings.
 * @param feature  Background feature to check.
 * @return Whether site settings has activated background panel.
 */
export function useHasBackgroundControl(
	settings: StyleSettings | undefined,
	feature:
		'backgroundImage' | 'backgroundSize' | 'gradient' | 'backgroundClip'
) {
	return settings?.background?.[ feature ];
}

/**
 * Checks site settings to see if the background panel may be used.
 * `settings.background.backgroundSize` exists also,
 * but can only be used if settings?.background?.backgroundImage is `true`.
 *
 * The panel is also shown when the block has color panel background
 * support (`settings.color.background`), because background color and
 * the legacy `color.gradient` control are rendered here.
 *
 * @param settings Site settings
 * @return Whether site settings has activated background panel.
 */
export function useHasBackgroundPanel( settings: StyleSettings | undefined ) {
	const hasBackgroundColor = useHasBackgroundColorPanel( settings );
	const { backgroundImage, gradient, backgroundClip } =
		settings?.background || {};
	return backgroundImage || gradient || backgroundClip || hasBackgroundColor;
}

/**
 * Checks if there is a current value in the background size block support
 * attributes. Background size values include background size as well
 * as background position.
 *
 * @param style Style attribute.
 * @return Whether the block has a background size value set.
 */
export function hasBackgroundSizeValue( style: PanelStyle | undefined ) {
	return (
		style?.background?.backgroundPosition !== undefined ||
		style?.background?.backgroundSize !== undefined
	);
}

/**
 * Returns the `background-clip` values a theme allows.
 *
 * @param settings Block settings.
 * @return Allowed values.
 */
export function getAllowedBackgroundClipValues(
	settings: StyleSettings | undefined
): string[] {
	const clipSetting = settings?.background?.backgroundClip;
	if ( true === clipSetting ) {
		return VALID_BACKGROUND_CLIP_VALUES;
	}
	return Array.isArray( clipSetting )
		? clipSetting.filter( ( clipValue ) =>
				VALID_BACKGROUND_CLIP_VALUES.includes( clipValue )
			)
		: [];
}

/**
 * Resolves the `background-clip` values a panel reads, and what they mean for
 * a text gradient. Shared by the Typography and Background panels.
 *
 * @param value          Style being edited.
 * @param baseValue      Default state style, set only while another state is selected.
 * @param inheritedValue Style the block inherits.
 * @return The clips, and which of them clips to the text.
 */
export function getBackgroundClipState(
	value: PanelStyle | undefined,
	baseValue?: PanelStyle,
	inheritedValue?: PanelStyle
) {
	const localClip = value?.background?.backgroundClip;
	const baseClip = baseValue?.background?.backgroundClip;
	const inheritedClip = inheritedValue?.background?.backgroundClip;

	return {
		localClip,
		baseClip,
		inheritedClip,
		isTextGradient: 'text' === localClip,
		isTextGradientFromBase: undefined === localClip && 'text' === baseClip,
		clipsToText: 'text' === ( localClip ?? baseClip ?? inheritedClip ),
	};
}

/**
 * Checks if there is a current value in the background image block support
 * attributes.
 *
 * @param style Style attribute.
 * @return Whether the block has a background image value set.
 */
export function hasBackgroundImageValue( style: PanelStyle | undefined ) {
	// The string form has no ID or URL property.
	const backgroundImage = style?.background?.backgroundImage as
		{ id?: number; url?: string } | undefined;
	return (
		!! backgroundImage?.id ||
		// Supports url() string values in theme.json.
		'string' === typeof style?.background?.backgroundImage ||
		!! backgroundImage?.url
	);
}

/**
 * Checks if there is a current value in the background gradient block support
 * attributes.
 *
 * @param style Style attribute.
 * @return Whether the block has a background gradient value set.
 */
export function hasBackgroundGradientValue( style: PanelStyle | undefined ) {
	return (
		'string' === typeof style?.background?.gradient &&
		style?.background?.gradient !== ''
	);
}

/**
 * Checks if there is a current value for the background color (written to
 * `color.background`).
 *
 * @param style Style attribute.
 * @return Whether the block has a background color value set.
 */
export function hasBackgroundColorValue( style: PanelStyle | undefined ) {
	return !! style?.color?.background;
}

/**
 * Checks if there is a current value in the legacy `color.gradient` location
 * (used by blocks with color panel gradient support that haven't adopted the
 * `background.gradient` block support).
 *
 * @param style Style attribute.
 * @return Whether the block has a legacy color gradient value set.
 */
export function hasLegacyColorGradientValue( style: PanelStyle | undefined ) {
	return !! style?.color?.gradient;
}

export function BackgroundToolsPanel( {
	resetAllFilter,
	onChange,
	value,
	panelId,
	children,
	headerLabel,
}: StyleToolsPanelProps ) {
	const dropdownMenuProps = useToolsPanelDropdownMenuProps();
	const resetAll = () => {
		const updatedValue = resetAllFilter( value );
		onChange( updatedValue );
	};

	return (
		<ToolsPanel
			// The background panel passes its heading.
			label={ headerLabel! }
			resetAll={ resetAll }
			panelId={ panelId }
			hasInnerWrapper
			className="background-block-support-panel"
			__experimentalFirstVisibleItemClass="first"
			__experimentalLastVisibleItemClass="last"
			dropdownMenuProps={ dropdownMenuProps }
		>
			<div className="background-block-support-panel__inner-wrapper">
				{ children }
			</div>
		</ToolsPanel>
	);
}

export default function BackgroundImagePanel( {
	as: Wrapper = BackgroundToolsPanel,
	value,
	onChange,
	inheritedValue = value,
	// Default state style, set only while another state is selected.
	baseValue,
	settings,
	panelId,
	defaultControls = DEFAULT_CONTROLS,
	defaultValues = {},
	headerLabel = __( 'Background' ),
	contrastWarning,
}: BackgroundPanelProps ) {
	const {
		colors,
		gradients,
		allColors,
		areCustomSolidsEnabled,
		areCustomGradientsEnabled,
		hasSolidColors,
		hasGradientColors,
		decodeValue,
		encodeGradientValue,
	} = useColorGradientSettings( settings );

	const hasBackgroundGradientControl = useHasBackgroundControl(
		settings,
		'gradient'
	);
	const hasColorPanelBackgroundSupport =
		useHasBackgroundColorPanel( settings );
	const showBackgroundColorControl =
		hasColorPanelBackgroundSupport && hasSolidColors;
	// New `background.gradient` block support — gradient lives under the
	// `background` style path.
	const showBackgroundGradientControl =
		hasGradientColors && hasBackgroundGradientControl;
	// Legacy `color.gradient` path — only rendered when the block has
	// color panel background support and hasn't adopted the newer
	// `background.gradient` support. Keeps the UI consistent for blocks
	// that still write gradients to `color.gradient`.
	const showLegacyColorGradientControl =
		hasColorPanelBackgroundSupport &&
		hasGradientColors &&
		! hasBackgroundGradientControl;
	const showBackgroundImageControl = useHasBackgroundControl(
		settings,
		'backgroundImage'
	);

	const allowedClipValues = getAllowedBackgroundClipValues( settings );
	// `text` alone is the Typography panel's Gradient control, not this one.
	const showBackgroundClipControl = allowedClipValues.some(
		( clipValue ) => clipValue !== 'text'
	);

	// A text gradient belongs to the Typography panel.
	const {
		localClip,
		baseClip,
		inheritedClip,
		isTextGradient,
		isTextGradientFromBase,
		clipsToText,
	} = getBackgroundClipState( value, baseValue, inheritedValue );
	const hasLocalClip = localClip !== undefined;
	const clipsToTextNotice = isTextGradientFromBase
		? __(
				'The gradient set in the Default state clips the background to the text, including any color or image.'
			)
		: __(
				'The gradient clips the background to the text, including any color or image.'
			);

	const resetAllFilter: PanelResetAllFilter = useCallback(
		( previousValue ) => {
			const clearsColorBackground = showBackgroundColorControl;
			const clearsColorGradient =
				hasBackgroundGradientControl || showLegacyColorGradientControl;
			// Without the clip control, keep the Typography panel's text gradient.
			const prevClip = previousValue?.background?.backgroundClip;
			const background =
				! showBackgroundClipControl && 'text' === prevClip
					? {
							gradient: previousValue?.background?.gradient,
							backgroundClip: prevClip,
						}
					: {};
			if ( ! clearsColorBackground && ! clearsColorGradient ) {
				return { ...previousValue, background };
			}
			return {
				...previousValue,
				background,
				color: {
					...previousValue?.color,
					...( clearsColorBackground && { background: undefined } ),
					...( clearsColorGradient && { gradient: undefined } ),
				},
			};
		},
		[
			hasBackgroundGradientControl,
			showBackgroundColorControl,
			showLegacyColorGradientControl,
			showBackgroundClipControl,
		]
	);

	if (
		! showBackgroundImageControl &&
		! showBackgroundColorControl &&
		! showBackgroundGradientControl &&
		! showLegacyColorGradientControl &&
		! showBackgroundClipControl
	) {
		return null;
	}

	const resetBackground = () =>
		onChange(
			setImmutably(
				value,
				[ 'background', 'backgroundImage' ],
				undefined
			)
		);

	const resetGradient = () => {
		let newValue = setImmutably(
			value,
			[ 'background', 'gradient' ],
			undefined
		);
		newValue = setImmutably( newValue, [ 'color', 'gradient' ], undefined );
		onChange( newValue );
	};

	const resetBackgroundClip = () =>
		onChange(
			setImmutably( value, [ 'background', 'backgroundClip' ], undefined )
		);

	// Non-cascading root values are already dropped from `inheritedValue` by
	// the builder, so inherited reads below are direct.

	// Background color (written to `color.background`).
	const backgroundColor = decodeValue( inheritedValue?.color?.background );
	const userBackgroundColor = decodeValue( value?.color?.background );
	const setBackgroundColor = ( newColor?: string, newSlug?: string ) => {
		const newValue = setImmutably(
			value,
			[ 'color', 'background' ],
			encodeColorValueWithPalette( allColors, newColor, newSlug )
		);
		// Legacy `color.gradient` is mutually exclusive with
		// `color.background`. `background.gradient` is independent and
		// should not be touched.
		if ( showLegacyColorGradientControl ) {
			// The color was just set.
			newValue.color!.gradient = undefined;
		}
		onChange( newValue );
	};
	const resetBackgroundColor = () => {
		const newValue = setImmutably(
			value,
			[ 'color', 'background' ],
			undefined
		);
		if ( showLegacyColorGradientControl ) {
			// The color was just set.
			newValue.color!.gradient = undefined;
		}
		onChange( newValue );
	};

	// Legacy `color.gradient` setters.
	const legacyColorGradient = decodeValue( inheritedValue?.color?.gradient );
	const userLegacyColorGradient = decodeValue( value?.color?.gradient );
	const setLegacyColorGradient = (
		newGradient?: string,
		newSlug?: string
	) => {
		const newValue = setImmutably(
			value,
			[ 'color', 'gradient' ],
			encodeGradientValue( newGradient, newSlug )
		);
		// The color was just set.
		newValue.color!.background = undefined;
		onChange( newValue );
	};
	const resetLegacyColorGradient = () =>
		onChange( setImmutably( value, [ 'color', 'gradient' ], undefined ) );

	// Get current gradient value, decoding preset slug references.
	// Fall back to color.gradient for legacy blocks that haven't migrated
	// to background.gradient yet (mirrors block inspector fallback in
	// packages/block-editor/src/hooks/background.jsx).
	// A text gradient belongs to the Typography panel, so neither the value
	// nor its slug is shown here.
	const currentGradientValue = isTextGradient
		? undefined
		: ( value?.background?.gradient ?? value?.color?.gradient );
	const inheritedGradientValue =
		inheritedClip === 'text'
			? undefined
			: ( inheritedValue?.background?.gradient ??
				inheritedValue?.color?.gradient );
	const currentGradient = decodeValue( currentGradientValue );
	const inheritedGradient = decodeValue( inheritedGradientValue );

	// Set gradient value, encoding preset matches as slug references.
	// Also clear color.gradient to migrate from the legacy location,
	// matching the block inspector behavior in hooks/background.jsx.
	const setGradient = ( newGradient?: string, newSlug?: string ) => {
		let newValue = setImmutably(
			value,
			[ 'background', 'gradient' ],
			encodeGradientValue( newGradient, newSlug )
		);
		newValue = setImmutably( newValue, [ 'color', 'gradient' ], undefined );
		// A text clip without a gradient leaves the text invisible.
		if ( ! newGradient && isTextGradient ) {
			newValue = setImmutably(
				newValue,
				[ 'background', 'backgroundClip' ],
				undefined
			);
		}
		onChange( newValue );
	};

	return (
		<Wrapper
			resetAllFilter={ resetAllFilter }
			value={ value }
			onChange={ onChange }
			panelId={ panelId }
			headerLabel={ headerLabel }
		>
			{ showBackgroundImageControl && (
				<ToolsPanelItem
					className="block-editor-color-gradient-item"
					hasValue={ () => hasBackgroundImageValue( value ) }
					label={ __( 'Image' ) }
					onDeselect={ resetBackground }
					isShownByDefault={ defaultControls.backgroundImage }
					panelId={ panelId }
				>
					<BackgroundImageControl
						value={ value }
						onChange={ onChange }
						settings={ settings }
						inheritedValue={ inheritedValue }
						// @ts-expect-error BackgroundImageControl takes no default controls.
						defaultControls={ defaultControls }
						defaultValues={ defaultValues }
					/>
				</ToolsPanelItem>
			) }
			{ showBackgroundColorControl && (
				<ColorGradientDropdownItem
					label={ __( 'Color' ) }
					hasValue={ () => hasBackgroundColorValue( value ) }
					resetValue={ resetBackgroundColor }
					isShownByDefault={ defaultControls.backgroundColor }
					indicators={ [ userBackgroundColor ?? backgroundColor ] }
					contrastWarning={ contrastWarning }
					tabs={ [
						{
							key: 'background',
							label: __( 'Color' ),
							inheritedValue: backgroundColor,
							// The picker selects by slug: `userSlug` when the
							// block has its own value, otherwise
							// `inheritedSlug`. Hex matching would mark two
							// same-hex presets as both selected.
							inheritedSlug: extractPresetSlug(
								inheritedValue?.color?.background,
								'color'
							),
							userSlug: extractPresetSlug(
								value?.color?.background,
								'color'
							),
							setValue: setBackgroundColor,
							userValue: userBackgroundColor,
							isPlaceholder:
								userBackgroundColor === undefined &&
								backgroundColor !== undefined,
						},
					] }
					colorGradientControlSettings={ {
						colors,
						disableCustomColors: ! areCustomSolidsEnabled,
					} }
					panelId={ panelId }
				/>
			) }
			{ showBackgroundGradientControl && (
				<ColorGradientDropdownItem
					label={ __( 'Gradient' ) }
					hasValue={ () =>
						hasBackgroundGradientValue( value ) && ! isTextGradient
					}
					resetValue={ resetGradient }
					isShownByDefault={ defaultControls.gradient }
					indicators={ [ currentGradient ?? inheritedGradient ] }
					tabs={ [
						{
							key: 'gradient',
							label: __( 'Gradient' ),
							inheritedValue: inheritedGradient,
							inheritedSlug: extractPresetSlug(
								inheritedGradientValue,
								'gradient'
							),
							userSlug: extractPresetSlug(
								currentGradientValue,
								'gradient'
							),
							setValue: setGradient,
							userValue: currentGradient,
							isGradient: true,
							isPlaceholder:
								currentGradient === undefined &&
								inheritedGradient !== undefined,
						},
					] }
					colorGradientControlSettings={ {
						gradients,
						disableCustomGradients: ! areCustomGradientsEnabled,
					} }
					panelId={ panelId }
				/>
			) }
			{ showLegacyColorGradientControl && (
				<ColorGradientDropdownItem
					label={ __( 'Gradient' ) }
					hasValue={ () => hasLegacyColorGradientValue( value ) }
					resetValue={ resetLegacyColorGradient }
					isShownByDefault={ defaultControls.gradient }
					indicators={ [
						userLegacyColorGradient ?? legacyColorGradient,
					] }
					tabs={ [
						{
							key: 'gradient',
							label: __( 'Gradient' ),
							inheritedValue: legacyColorGradient,
							inheritedSlug: extractPresetSlug(
								inheritedValue?.color?.gradient,
								'gradient'
							),
							userSlug: extractPresetSlug(
								value?.color?.gradient,
								'gradient'
							),
							setValue: setLegacyColorGradient,
							userValue: userLegacyColorGradient,
							isGradient: true,
							isPlaceholder:
								userLegacyColorGradient === undefined &&
								legacyColorGradient !== undefined,
						},
					] }
					colorGradientControlSettings={ {
						gradients,
						disableCustomGradients: ! areCustomGradientsEnabled,
					} }
					panelId={ panelId }
				/>
			) }
			{ showBackgroundClipControl && (
				<ToolsPanelItem
					className="block-editor-background-panel__clip-item"
					label={ __( 'Clip' ) }
					// Keeps a text gradient from surfacing this control.
					hasValue={ () => hasLocalClip && ! isTextGradient }
					onDeselect={ resetBackgroundClip }
					isShownByDefault={ defaultControls.backgroundClip }
					panelId={ panelId }
				>
					<BackgroundClipControl
						// Clip values are keywords.
						value={
							( localClip ?? baseClip ?? inheritedClip ) as
								string | undefined
						}
						onChange={ ( newClip ) =>
							onChange(
								setImmutably(
									value,
									[ 'background', 'backgroundClip' ],
									newClip
								)
							)
						}
						allowedValues={ allowedClipValues }
					/>
				</ToolsPanelItem>
			) }
			{ clipsToText && (
				<Notice.Root
					intent="info"
					className="block-editor-background-panel__clips-to-text-notice"
				>
					<Notice.Description>
						{ clipsToTextNotice }
					</Notice.Description>
				</Notice.Root>
			) }
		</Wrapper>
	);
}
